INSERT INTO site_areas (slug,area_type,country_code,name_ar,name_en,name_fr,currency_code,currency_symbol) VALUES ('finland','country','FI','فنلندا','Finland','Finlande','EUR','€') ON CONFLICT (slug) DO UPDATE SET name_ar=EXCLUDED.name_ar,name_en=EXCLUDED.name_en,currency_code='EUR',currency_symbol='€',is_active=TRUE,updated_at=NOW();
INSERT INTO area_content (area_id,content_key,content_ar,content_en,content_type,section,sort_order) SELECT id,v.k,v.ar,v.en,'text',v.s,v.o FROM site_areas JOIN (VALUES ('seo_title','تحفيظ القرآن وتأسيس العربية أونلاين في فنلندا | أكاديمية الحافظ','Online Quran and Arabic Foundations in Finland','seo',0),('seo_description','تحفيظ القرآن الكريم وتأسيس اللغة العربية أونلاين من فنلندا بحصص فردية وأسعار باليورو.','Online Quran memorization and Arabic foundations from Finland with individual lessons and EUR prices.','seo',1),('local_card','Al-Hafiz Academy offers individual online lessons for Quran memorization and Arabic foundations for Arabic-speaking learners in Finland. Helsinki, Espoo, Tampere and Turku are geographic references for this page. Learning is online, communication is in Arabic, and there is no local office, branch or teaching location in Finland.','Online Quran memorization and Arabic foundations for Arabic-speaking learners in Finland.','local',0)) v(k,ar,en,s,o) ON site_areas.slug='finland' ON CONFLICT (area_id,content_key) DO UPDATE SET content_ar=EXCLUDED.content_ar,content_en=EXCLUDED.content_en,is_active=TRUE;
INSERT INTO area_packages (area_id,program,package_key,name_ar,name_en,description_ar,price,currency_code,sessions_per_month,is_active,sort_order) SELECT id,v.p,v.k,v.n,v.n,v.d,v.price,'EUR',v.sessions,TRUE,v.o FROM site_areas JOIN (VALUES ('quran','quran-4','تحفيظ القرآن — 4 حصص','Quran memorization',13,'حفظ ومراجعة فردية',4,0),('quran','quran-8','تحفيظ القرآن — 8 حصص','Quran memorization',24,'حفظ ومراجعة فردية',8,1),('quran','quran-12','تحفيظ القرآن — 12 حصة','Quran memorization',36,'حفظ ومراجعة فردية',12,2),('quran','quran-16','تحفيظ القرآن — 16 حصة','Quran memorization',48,'حفظ ومراجعة فردية',16,3),('arabic','arabic-4','تأسيس العربية — 4 حصص','Arabic foundations',17,'قراءة وفهم',4,0),('arabic','arabic-8','تأسيس العربية — 8 حصص','Arabic foundations',31,'قراءة وفهم',8,1),('arabic','arabic-12','تأسيس العربية — 12 حصة','Arabic foundations',47,'قراءة وفهم',12,2),('arabic','arabic-16','تأسيس العربية — 16 حصة','Arabic foundations',63,'قراءة وفهم',16,3)) v(p,k,n,d,price,desc,sessions,o) ON site_areas.slug='finland' ON CONFLICT (area_id,package_key) DO UPDATE SET price=EXCLUDED.price,name_ar=EXCLUDED.name_ar,program=EXCLUDED.program,is_active=TRUE;
INSERT INTO area_faq_items (area_id,question_key,question_ar,question_en,answer_ar,answer_en,sort_order) SELECT id,v.k,v.q,v.q,v.a,v.a,v.o FROM site_areas JOIN (VALUES ('fi-1','هل الدراسة أونلاين من فنلندا؟','نعم، الدراسة أونلاين، والمدن المذكورة سياق جغرافي للصفحة فقط دون مقرات أو فروع أو أماكن تدريس محلية.',0),('fi-2','هل الأسعار باليورو؟','نعم، الأسعار الظاهرة في صفحة فنلندا باليورو.',1),('fi-3','ما مدة الحصة الأساسية؟','مدة الحصة الأساسية المعروضة 30 دقيقة.',2),('fi-4','بأي لغة يتم التواصل؟','يتم التواصل مع الأكاديمية باللغة العربية.',3),('fi-5','هل توجد باقات مخصصة؟','يوجد باقات مخصصة.',4)) v(k,q,a,o) ON site_areas.slug='finland' ON CONFLICT (area_id,question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar,answer_ar=EXCLUDED.answer_ar,is_active=TRUE;
INSERT INTO area_links (area_id,link_key,label_ar,label_en,href,link_type,is_external,sort_order) SELECT id,v.k,v.l,v.l,v.h,v.t,v.x,v.o FROM site_areas JOIN (VALUES ('canonical','الصفحة الرسمية','https://quran-elhafez.com/finland','canonical',TRUE,0),('whatsapp','واتساب','https://bit.ly/4aJfOl6','external',TRUE,1),('home','الرئيسية','/','internal',FALSE,2),('games','الألعاب والمسابقات','/games','internal',FALSE,3),('library','المكتبة','/library','internal',FALSE,4)) v(k,l,h,t,x,o) ON site_areas.slug='finland' ON CONFLICT (area_id,link_key) DO UPDATE SET href=EXCLUDED.href,label_ar=EXCLUDED.label_ar,is_active=TRUE;
INSERT INTO area_themes (area_id,theme_name_ar,theme_name_en,primary_color,secondary_color,accent_color,background_color,text_color) SELECT id,'مساحة تركيز فنلندا','Finland focus space','#183B56','#B9D9E8','#E7D878','#F8FAFC','#183B56' FROM site_areas WHERE slug='finland' ON CONFLICT (area_id) DO UPDATE SET primary_color=EXCLUDED.primary_color,secondary_color=EXCLUDED.secondary_color,accent_color=EXCLUDED.accent_color,background_color=EXCLUDED.background_color,text_color=EXCLUDED.text_color,is_active=TRUE;
INSERT INTO area_cities (area_id,city_key,name_ar,name_en,region_name,sort_order) SELECT id,v.k,v.a,v.e,v.r,v.o FROM site_areas JOIN (VALUES ('helsinki','هلسنكي','Helsinki','Uusimaa',10),('espoo','إسبو','Espoo','Uusimaa',20),('tampere','تامبيري','Tampere','Pirkanmaa',30),('turku','توركو','Turku','Southwest Finland',40)) v(k,a,e,r,o) ON site_areas.slug='finland' ON CONFLICT (area_id,city_key) DO UPDATE SET name_ar=EXCLUDED.name_ar,name_en=EXCLUDED.name_en,is_active=TRUE;
INSERT INTO area_timezones (area_id,timezone_name,label_ar,label_en,is_primary,sort_order) SELECT id,'Europe/Helsinki','توقيت فنلندا (Europe/Helsinki)','Finland Time',TRUE,10 FROM site_areas WHERE slug='finland' ON CONFLICT (area_id,timezone_name) DO UPDATE SET label_ar=EXCLUDED.label_ar,is_primary=TRUE,is_active=TRUE;
